package com.hrcoresystem.hrcore_api.modules.tenant.employees.application.usecase;
import com.hrcoresystem.hrcore_api.modules.platform.tenantsettings.application.service.TenantTimezoneService; import com.hrcoresystem.hrcore_api.modules.tenant.employees.application.service.EmployeeSupervisionScopeService; import com.hrcoresystem.hrcore_api.modules.tenant.departments.application.dto.OrganizationalEmployeeSummaryResponse; import com.hrcoresystem.hrcore_api.modules.tenant.employees.domain.repository.OrganizationalEmployeeQueryRepository; import org.springframework.data.domain.*; import org.springframework.stereotype.Service;
@Service public class ListMyTeamEmployeesUseCase { private final EmployeeSupervisionScopeService scope; private final OrganizationalEmployeeQueryRepository query; private final TenantTimezoneService timezone; public ListMyTeamEmployeesUseCase(EmployeeSupervisionScopeService s,OrganizationalEmployeeQueryRepository q,TenantTimezoneService t){scope=s;query=q;timezone=t;} public Page<OrganizationalEmployeeSummaryResponse> execute(Pageable page){return query.findBySupervisor(scope.requireCurrentEmployeeId(),timezone.today(),page);} }
